using UnityEngine;

public class HitscanWeapon : MonoBehaviour
{
    [Header("Stats")]
    public float damage = 25f;
    public float range = 200f;
    public float fireRate = 0.1f;
    public int maxAmmo = 30;
    public float reloadTime = 2f;
    public int bulletsPerShot = 1;
    public float spread = 0.01f;

    [Header("Components")]
    public Camera playerCamera;
    public Transform barrelTip;
    public ParticleSystem muzzleFlash;
    public TrailRenderer bulletTrail;
    public AudioClip shootSound;
    public GameObject impactEffect;

    [Header("Recoil")]
    public float recoilAmount = 2f;
    public float recoilRecoverySpeed = 5f;

    private int currentAmmo;
    private float nextFireTime;
    private bool isReloading;
    private float currentRecoil;
    private AudioSource audioSource;

    void Awake()
    {
        currentAmmo = maxAmmo;
        audioSource = GetComponent<AudioSource>();
    }

    void Update()
    {
        // Recoil recovery
        currentRecoil = Mathf.Lerp(currentRecoil, 0f, recoilRecoverySpeed * Time.deltaTime);

        if (isReloading) return;

        if (Input.GetButton("Fire1") && Time.time >= nextFireTime && currentAmmo > 0)
        {
            Fire();
        }

        if (Input.GetKeyDown(KeyCode.R) && currentAmmo < maxAmmo)
        {
            StartCoroutine(Reload());
        }
    }

    void Fire()
    {
        currentAmmo--;
        nextFireTime = Time.time + fireRate;

        // Visual feedback
        muzzleFlash.Play();
        audioSource.PlayOneShot(shootSound);
        currentRecoil += recoilAmount;

        for (int i = 0; i < bulletsPerShot; i++)
        {
            // Calculate spread
            Vector3 spreadVec = Random.insideUnitSphere * spread;
            Vector3 direction = playerCamera.transform.forward + spreadVec;

            // Raycast for hit detection
            RaycastHit hit;
            if (Physics.Raycast(playerCamera.transform.position, direction.normalized, out hit, range))
            {
                // Spawn bullet trail
                TrailRenderer trail = Instantiate(bulletTrail, barrelTip.position, Quaternion.identity);
                StartCoroutine(MoveTrail(trail, hit.point));

                // Apply damage
                IDamageable damageable = hit.collider.GetComponent<IDamageable>();
                if (damageable != null)
                {
                    damageable.TakeDamage(damage, barrelTip.position, hit.point, hit.normal);
                }

                // Surface effects
                SpawnImpactEffect(hit.point, hit.normal, hit.collider.tag);
            }
        }
    }

    IEnumerator MoveTrail(TrailRenderer trail, Vector3 target)
    {
        float time = 0;
        Vector3 start = trail.transform.position;
        while (time < 0.1f)
        {
            trail.transform.position = Vector3.Lerp(start, target, time / 0.1f);
            time += Time.deltaTime;
            yield return null;
        }
        trail.transform.position = target;
    }

    IEnumerator Reload()
    {
        isReloading = true;
        // Play reload animation/sound
        yield return new WaitForSeconds(reloadTime);
        currentAmmo = maxAmmo;
        isReloading = false;
    }

    void SpawnImpactEffect(Vector3 point, Vector3 normal, string surfaceTag)
    {
        // Different effects for different surfaces
        GameObject effect = Instantiate(impactEffect, point, Quaternion.LookRotation(normal));
        Destroy(effect, 2f);
    }

    // Call this from camera controller for recoil
    public float GetRecoil() => currentRecoil;
}

