using UnityEngine;

// ========== COMBAT STATE MACHINE ==========
public enum CombatState { Idle, Attacking, ComboReady, Recovery, Staggered, Blocking, Dodging }

public class MeleeCombat : MonoBehaviour
{
    [Header("Weapon Stats")]
    public float lightAttackDamage = 25f;
    public float heavyAttackDamage = 50f;
    public float lightAttackDuration = 0.4f;
    public float heavyAttackDuration = 0.8f;
    public float comboWindow = 0.3f;
    public float staminaCost = 10f;
    public float recoveryTime = 0.2f;

    [Header("References")]
    public Animator animator;
    public Transform weaponHitbox;
    public LayerMask targetLayer;
    public Collider weaponCollider;

    private CombatState state = CombatState.Idle;
    private float stateTimer = 0f;
    private int comboStep = 0;
    private bool inputBuffered = false;
    private string bufferedInput = "";
    private HealthController health;
    private StaminaController stamina;
    private List<GameObject> alreadyHit = new List<GameObject>();

    // Animation hashes
    private static readonly int Attack1 = Animator.StringToHash("Attack1");
    private static readonly int Attack2 = Animator.StringToHash("Attack2");
    private static readonly int Attack3 = Animator.StringToHash("Attack3");
    private static readonly int HeavyAttack = Animator.StringToHash("HeavyAttack");
    private static readonly int HitStun = Animator.StringToHash("HitStun");
    private static readonly int IsBlocking = Animator.StringToHash("IsBlocking");
    private static readonly int Dodge = Animator.StringToHash("Dodge");

    void Awake()
    {
        health = GetComponent<HealthController>();
        stamina = GetComponent<StaminaController>();
        weaponCollider.enabled = false;
    }

    void Update()
    {
        stateTimer -= Time.deltaTime;

        switch (state)
        {
            case CombatState.Idle:
                HandleIdleInput();
                break;
            case CombatState.Attacking:
                if (inputBuffered && comboStep < 2 && stateTimer > 0)
                {
                    // Input buffered during attack window
                }
                if (stateTimer <= 0)
                {
                    if (inputBuffered && comboStep < 2)
                    {
                        ExecuteCombo(bufferedInput);
                    }
                    else
                    {
                        transitionToState(CombatState.Recovery, recoveryTime);
                        comboStep = 0;
                    }
                }
                break;
            case CombatState.ComboReady:
                if (inputBuffered)
                {
                    ExecuteCombo(bufferedInput);
                }
                if (stateTimer <= 0)
                {
                    transitionToState(CombatState.Recovery, 0.1f);
                    comboStep = 0;
                }
                break;
            case CombatState.Recovery:
                if (stateTimer <= 0)
                    transitionToState(CombatState.Idle, 0);
                break;
            case CombatState.Staggered:
                // Can't act until stagger ends
                break;
        }
    }

    void HandleIdleInput()
    {
        if (Input.GetMouseButtonDown(0) && stamina.HasEnough(staminaCost))
        {
            ExecuteAttack("light");
        }
        else if (Input.GetMouseButtonDown(1))
        {
            ExecuteAttack("heavy");
        }
        else if (Input.GetKeyDown(KeyCode.LeftControl))
        {
            transitionToState(CombatState.Blocking, 0);
            animator.SetBool(IsBlocking, true);
        }
        else if (Input.GetKeyDown(KeyCode.Space))
        {
            ExecuteDodge();
        }

        // Buffered input during attacks
        if (Input.GetMouseButtonDown(0) && state != CombatState.Idle)
        {
            inputBuffered = true;
            bufferedInput = "light";
        }
        else if (Input.GetMouseButtonDown(1) && state != CombatState.Idle)
        {
            inputBuffered = true;
            bufferedInput = "heavy";
        }
    }

    void ExecuteAttack(string type)
    {
        stamina.Consume(staminaCost);
        alreadyHit.Clear();

        if (type == "light")
        {
            comboStep++;
            if (comboStep == 1)
            {
                animator.SetTrigger(Attack1);
                transitionToState(CombatState.Attacking, lightAttackDuration);
            }
            else if (comboStep == 2)
            {
                animator.SetTrigger(Attack2);
                transitionToState(CombatState.Attacking, lightAttackDuration * 1.1f);
            }
            else if (comboStep == 3)
            {
                animator.SetTrigger(Attack3);
                transitionToState(CombatState.Attacking, lightAttackDuration * 1.3f);
                // Final hit: bonus damage, knockback
            }
        }
        else
        {
            animator.SetTrigger(HeavyAttack);
            transitionToState(CombatState.Attacking, heavyAttackDuration);
            comboStep = 0;
        }

        inputBuffered = false;
        bufferedInput = "";

        // Enable weapon hitbox during specific animation frames
        // Called by animation events:
        // EnableWeaponHitbox() / DisableWeaponHitbox()
    }

    void ExecuteCombo(string input)
    {
        comboStep++;
        inputBuffered = false;
        bufferedInput = "";

        animator.SetTrigger(comboStep == 2 ? Attack2 : Attack3);
        float duration = lightAttackDuration * (1f + comboStep * 0.1f);
        transitionToState(CombatState.Attacking, duration);
    }

    // Called by animation events
    public void EnableWeaponHitbox() { weaponCollider.enabled = true; }
    public void DisableWeaponHitbox() { weaponCollider.enabled = false; }

    void OnTriggerEnter(Collider other)
    {
        if (!other.gameObject.CompareTag("Enemy")) return;
        if (alreadyHit.Contains(other.gameObject)) return;

        alreadyHit.Add(other.gameObject);
        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            float finalDamage = lightAttackDamage;
            if (comboStep == 3) finalDamage *= 1.5f;

            Vector3 hitDir = (other.transform.position - transform.position).normalized;
            damageable.TakeDamage(finalDamage, hitDir);

            // Hitstop (time freeze on impact for game feel)
            StartCoroutine(Hitstop(0.05f));
        }
    }

    IEnumerator Hitstop(float duration)
    {
        Time.timeScale = 0f;
        yield return new WaitForSecondsRealtime(duration);
        Time.timeScale = 1f;
    }

    void transitionToState(CombatState newState, float timer)
    {
        state = newState;
        stateTimer = timer;
    }

    public void OnHitReceived(float damage, Vector3 direction)
    {
        if (state == CombatState.Blocking)
        {
            // Block: reduced damage, stamina cost
            stamina.Consume(damage * 0.5f);
            if (stamina.current <= 0)
            {
                // Guard break - take full damage, stagger
                transitionToState(CombatState.Staggered, 1f);
                animator.SetTrigger(HitStun);
            }
        }
        else
        {
            transitionToState(CombatState.Staggered, 0.5f);
            animator.SetTrigger(HitStun);
        }
    }
}

