using UnityEngine;
using UnityEngine.UI;
using System.Collections.Generic;
using TMPro;

[System.Serializable]
public class DialogueNode
{
    public string speakerName;
    [TextArea(3, 5)] public string dialogueText;
    public AudioClip voiceLine;
    public float displayDuration = 3f;
    public DialogueChoice[] choices;
    public string onCompleteEvent; // "open_door", "spawn_enemy", etc.
}

[System.Serializable]
public class DialogueChoice
{
    public string choiceText;
    public int nextNodeIndex; // -1 = end conversation
    public string requiredFlag; // "has_key" - leave empty if no requirement
}

public class DialogueSystem : MonoBehaviour
{
    [Header("Dialogue Data")]
    public DialogueNode[] nodes;

    [Header("UI References")]
    public GameObject dialoguePanel;
    public TextMeshProUGUI speakerText;
    public TextMeshProUGUI dialogueText;
    public Transform choicesContainer;
    public GameObject choiceButtonPrefab;
    public Image speakerPortrait;

    private int currentNode = 0;
    private bool isDialogueActive = false;
    private AudioSource audioSource;
    private Queue<string> eventQueue = new Queue<string>();

    void Awake()
    {
        audioSource = GetComponent<AudioSource>();
    }

    public void StartDialogue(int startNode = 0)
    {
        currentNode = startNode;
        isDialogueActive = true;
        dialoguePanel.SetActive(true);
        Cursor.lockState = CursorLockMode.None;
        Cursor.visible = true;
        ShowNode(currentNode);
    }

    void ShowNode(int index)
    {
        if (index < 0 || index >= nodes.Length)
        {
            EndDialogue();
            return;
        }

        DialogueNode node = nodes[index];
        speakerText.text = node.speakerName;
        dialogueText.text = node.dialogueText;

        // Typewriter effect
        StopAllCoroutines();
        StartCoroutine(TypewriterEffect(node.dialogueText, node.displayDuration));

        // Voice
        if (node.voiceLine != null && audioSource != null)
        {
            audioSource.clip = node.voiceLine;
            audioSource.Play();
        }

        // Choices
        ClearChoices();
        if (node.choices != null && node.choices.Length > 0)
        {
            foreach (DialogueChoice choice in node.choices)
            {
                // Check requirements
                if (!string.IsNullOrEmpty(choice.requiredFlag))
                {
                    if (!GameManager.Instance.HasFlag(choice.requiredFlag))
                        continue;
                }

                GameObject btn = Instantiate(choiceButtonPrefab, choicesContainer);
                btn.GetComponentInChildren<TextMeshProUGUI>().text = choice.choiceText;
                int nextIdx = choice.nextNodeIndex;
                btn.GetComponent<Button>().onClick.AddListener(() => OnChoiceSelected(nextIdx));
            }
        }
        else
        {
            // No choices - auto-advance or wait for click
            // The Continue() button handles this
        }

        // Fire event
        if (!string.IsNullOrEmpty(node.onCompleteEvent))
        {
            eventQueue.Enqueue(node.onCompleteEvent);
        }
    }

    IEnumerator TypewriterEffect(string text, float duration)
    {
        dialogueText.text = "";
        float charDelay = duration / text.Length;
        foreach (char c in text)
        {
            dialogueText.text += c;
            yield return new WaitForSeconds(charDelay);
        }
    }

    public void Continue()
    {
        DialogueNode node = nodes[currentNode];
        if (node.choices == null || node.choices.Length == 0)
        {
            currentNode++;
            ShowNode(currentNode);
        }
        // If there are choices, player must pick one
    }

    void OnChoiceSelected(int nextNode)
    {
        if (nextNode == -1)
        {
            EndDialogue();
        }
        else
        {
            currentNode = nextNode;
            ShowNode(currentNode);
        }
    }

    void EndDialogue()
    {
        isDialogueActive = false;
        dialoguePanel.SetActive(false);
        Cursor.lockState = CursorLockMode.Locked;
        Cursor.visible = false;

        // Process queued events
        while (eventQueue.Count > 0)
        {
            string evt = eventQueue.Dequeue();
            GameManager.Instance.ProcessEvent(evt);
        }
    }

    void ClearChoices()
    {
        foreach (Transform child in choicesContainer)
            Destroy(child.gameObject);
    }

    void Update()
    {
        if (isDialogueActive && Input.GetKeyDown(KeyCode.Space))
        {
            Continue();
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using TMPro;
using System.Collections;

public class GameHUD : MonoBehaviour
{
    [Header("Status Bars")]
    public Slider healthBar;
    public Slider staminaBar;
    public Slider experienceBar;
    public TextMeshProUGUI healthText;
    public TextMeshProUGUI levelText;

    [Header("Ammo & Weapons")]
    public TextMeshProUGUI ammoText;
    public TextMeshProUGUI weaponNameText;
    public Image weaponIcon;

    [Header("Notifications")]
    public GameObject notificationPrefab;
    public Transform notificationContainer;
    public float notificationDuration = 3f;

    [Header("Crosshair")]
    public RectTransform crosshair;
    public float crosshairSpread = 10f;
    public float crosshairRecoveryRate = 5f;

    [Header("Damage Direction")]
    public Image damageDirectionalIndicator;
    public float damageIndicatorDuration = 1f;

    [Header("Minimap")]
    public RawImage minimapImage;
    public Transform playerIcon;
    public float minimapRadius = 50f;

    [Header("Boss Health")]
    public GameObject bossHealthPanel;
    public Slider bossHealthBar;
    public TextMeshProUGUI bossNameText;

    [Header("Screen Effects")]
    public Image damageVignette;
    public Image lowHealthVignette;
    public float damageVignetteDuration = 0.5f;

    [Header("Controller Navigation")]
    public GameObject defaultSelectedButton;

    private float currentCrosshairSpread;
    private Coroutine damageVignetteCoroutine;

    void Start()
    {
        // Initialize
        healthBar.maxValue = 100;
        healthBar.value = 100;
        UpdateHealthText(100, 100);

        // Set up controller navigation
        if (defaultSelectedButton != null)
        {
            UnityEngine.EventSystems.EventSystem.current.SetSelectedGameObject(defaultSelectedButton);
        }

        // Hide boss HP
        bossHealthPanel.SetActive(false);
        damageVignette.color = Color.clear;
        lowHealthVignette.color = Color.clear;
    }

    // ====== HEALTH SYSTEM ======
    public void UpdateHealth(float current, float max)
    {
        healthBar.maxValue = max;
        healthBar.value = current;
        UpdateHealthText(current, max);

        // Low health effect
        float healthPercent = current / max;
        lowHealthVignette.color = new Color(1, 0, 0, Mathf.Lerp(0.4f, 0f, healthPercent));
        lowHealthVignette.CrossFadeAlpha(healthPercent < 0.3f ? 0.4f : 0f, 1f, true);
    }

    void UpdateHealthText(float current, float max)
    {
        healthText.text = $"{Mathf.CeilToInt(current)}/{Mathf.CeilToInt(max)}";
    }

    // ====== STAMINA ======
    public void UpdateStamina(float current, float max)
    {
        staminaBar.maxValue = max;
        staminaBar.value = current;
    }

    // ====== EXPERIENCE & LEVEL ======
    public void UpdateExperience(float current, float max, int level)
    {
        experienceBar.maxValue = max;
        experienceBar.value = current;
        levelText.text = $"LV {level}";
    }

    // ====== AMMO ======
    public void UpdateAmmo(int current, int max, string weaponName, Sprite icon)
    {
        ammoText.text = $"{current}/{max}";
        weaponNameText.text = weaponName;
        if (icon != null) weaponIcon.sprite = icon;

        // Low ammo warning
        ammoText.color = current <= 0 ? Color.red :
                         current <= max * 0.2f ? Color.yellow :
                         Color.white;
    }

    // ====== CROSSHAIR ======
    public void SetCrosshairSpread(float amount)
    {
        currentCrosshairSpread = Mathf.Max(currentCrosshairSpread, amount);
    }

    void UpdateCrosshair()
    {
        // Recover spread over time
        currentCrosshairSpread = Mathf.Lerp(currentCrosshairSpread, crosshairSpread,
            crosshairRecoveryRate * Time.deltaTime);

        if (crosshair != null)
        {
            // Using child elements for each crosshair line
            float spread = currentCrosshairSpread;
            crosshair.Find("Top").GetComponent<RectTransform>().anchoredPosition = new Vector2(0, spread);
            crosshair.Find("Bottom").GetComponent<RectTransform>().anchoredPosition = new Vector2(0, -spread);
            crosshair.Find("Left").GetComponent<RectTransform>().anchoredPosition = new Vector2(-spread, 0);
            crosshair.Find("Right").GetComponent<RectTransform>().anchoredPosition = new Vector2(spread, 0);
        }
    }

    // ====== DAMAGE INDICATOR ======
    public void ShowDamageDirection(Vector3 damageDirection)
    {
        if (damageDirectionalIndicator == null) return;

        // Convert world direction to screen rotation
        float angle = Mathf.Atan2(damageDirection.x, damageDirection.z) * Mathf.Rad2Deg;
        damageDirectionalIndicator.transform.rotation = Quaternion.Euler(0, 0, angle);

        if (damageVignetteCoroutine != null)
            StopCoroutine(damageVignetteCoroutine);
        damageVignetteCoroutine = StartCoroutine(FlashDamageVignette());
    }

    IEnumerator FlashDamageVignette()
    {
        damageVignette.color = new Color(1, 0, 0, 0.3f);
        yield return new WaitForSeconds(damageVignetteDuration);
        damageVignette.CrossFadeAlpha(0f, 0.5f, true);
    }

    // ====== NOTIFICATIONS ======
    public void ShowNotification(string message, Color color, Sprite icon = null)
    {
        GameObject notif = Instantiate(notificationPrefab, notificationContainer);
        TextMeshProUGUI text = notif.GetComponentInChildren<TextMeshProUGUI>();
        text.text = message;
        text.color = color;

        if (icon != null)
        {
            Image iconImg = notif.transform.Find("Icon").GetComponent<Image>();
            iconImg.sprite = icon;
            iconImg.enabled = true;
        }

        Destroy(notif, notificationDuration);
    }

    // ====== BOSS HEALTH ======
    public void ShowBossHealth(string bossName, float maxHealth)
    {
        bossHealthPanel.SetActive(true);
        bossNameText.text = bossName;
        bossHealthBar.maxValue = maxHealth;
        bossHealthBar.value = maxHealth;
    }

    public void UpdateBossHealth(float current)
    {
        bossHealthBar.value = current;
    }

    public void HideBossHealth()
    {
        StartCoroutine(FadeOutBossHealth());
    }

    IEnumerator FadeOutBossHealth()
    {
        CanvasGroup group = bossHealthPanel.GetComponent<CanvasGroup>();
        if (group == null) group = bossHealthPanel.AddComponent<CanvasGroup>();

        float elapsed = 0;
        while (elapsed < 1f)
        {
            group.alpha = 1 - elapsed;
            elapsed += Time.deltaTime * 2;
            yield return null;
        }
        bossHealthPanel.SetActive(false);
        group.alpha = 1;
    }

    // ====== DAMAGE FLOATING TEXT ======
    public void ShowDamageNumber(Vector3 worldPosition, float damage, bool isCritical = false)
    {
        // Convert world position to screen
        Vector3 screenPos = Camera.main.WorldToScreenPoint(worldPosition);

